import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  getAppointments,
  getPatients,
  getPayments,
} from '../services/api';
import './Dashboard.css';

export default function Dashboard() {
  const [user, setUser] = useState(null);
  const [stats, setStats] = useState({
    patients: 0,
    appointmentsToday: 0,
    appointmentsWeek: 0,
    incomeMonth: 0,
  });
  const [upcoming, setUpcoming] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const userData = localStorage.getItem('user');
    if (!userData) {
      navigate('/login');
    } else {
      setUser(JSON.parse(userData));
    }
  }, [navigate]);

  useEffect(() => {
    const loadStats = async () => {
      try {
        const [patientsRes, appointmentsRes, paymentsRes] = await Promise.all([
          getPatients(),
          getAppointments(),
          getPayments(),
        ]);

        const patients = patientsRes.data || [];
        const appointments = appointmentsRes.data || [];
        const payments = paymentsRes.data || [];

        const today = new Date();
        const startOfWeek = new Date(today);
        startOfWeek.setDate(today.getDate() - today.getDay());
        const endOfWeek = new Date(startOfWeek);
        endOfWeek.setDate(startOfWeek.getDate() + 6);

        const appointmentsToday = appointments.filter((appointment) => {
          const appointmentDate = new Date(appointment.appointmentDate);
          return (
            appointmentDate.getFullYear() === today.getFullYear() &&
            appointmentDate.getMonth() === today.getMonth() &&
            appointmentDate.getDate() === today.getDate()
          );
        }).length;

        const appointmentsWeek = appointments.filter((appointment) => {
          const appointmentDate = new Date(appointment.appointmentDate);
          return appointmentDate >= startOfWeek && appointmentDate <= endOfWeek;
        }).length;

        const incomeMonth = payments.reduce((sum, payment) => {
          if (!payment.paymentDate) return sum;
          const date = new Date(payment.paymentDate);
          if (
            date.getFullYear() === today.getFullYear() &&
            date.getMonth() === today.getMonth()
          ) {
            return sum + Number(payment.amount || 0);
          }
          return sum;
        }, 0);

        const upcomingAppointments = appointments
          .filter((appointment) => new Date(appointment.appointmentDate) >= today)
          .sort((a, b) => new Date(a.appointmentDate) - new Date(b.appointmentDate))
          .slice(0, 5);

        setStats({
          patients: patients.length,
          appointmentsToday,
          appointmentsWeek,
          incomeMonth,
        });
        setUpcoming(upcomingAppointments);
      } catch (error) {
        console.error('Error cargando estadísticas:', error);
      } finally {
        setLoading(false);
      }
    };

    loadStats();
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    navigate('/login');
  };

  if (!user) return <div className="loading">Cargando...</div>;

  return (
    <div className="dashboard-layout">
      <aside className="sidebar">
        <div className="brand">
          <span>🩺</span>
          <h1>Salud System</h1>
        </div>

        <div className="section-title">Menú</div>
        <nav>
          <button className="active">Dashboard</button>
          <button onClick={() => navigate('/appointments')}>Calendario</button>
          <button onClick={() => navigate('/appointments')}>Citas</button>
          <button onClick={() => navigate('/patients')}>Pacientes</button>
          <button onClick={() => navigate('/payments')}>Pagos</button>
          <button onClick={() => navigate('/reports')}>Reportes</button>
          {user.role === 'admin' && <button onClick={() => navigate('/configuration')}>Configuración</button>}
        </nav>

        <div className="section-title">Cuenta</div>
        <div className="user-box">
          <div>
            <strong>{user.firstName} {user.lastName}</strong>
            <p>{user.role}</p>
          </div>
        </div>

        <button onClick={handleLogout} className="logout-btn">Cerrar sesión</button>
      </aside>

      <div className="main-panel">
        <div className="topbar">
          <h2>Dashboard</h2>
          <div className="user-box">
            <div className="user-name">
              <span>Bienvenido</span>
              <strong>{user.firstName}</strong>
            </div>
          </div>
        </div>

        <div className="content-body">
          <div className="hero-card">
            <div className="hero-text">
              <h3>Bienvenido al Control de Salud</h3>
              <p>Administra pacientes, citas y pagos desde un tablero moderno. Todo está pensado para darte visibilidad rápida y acceso inmediato.</p>
            </div>
            <div className="hero-actions">
              <button onClick={() => navigate('/appointments')}>Nueva Cita</button>
              <button onClick={() => navigate('/patients')}>Nuevo Paciente</button>
              <button onClick={() => navigate('/payments')}>Gestionar Pagos</button>
              <button onClick={() => navigate('/reports')}>Ver Reportes</button>
            </div>
          </div>

          <div className="summary-grid">
            <div className="summary-card">
              <h4>Citas hoy</h4>
              <p>{loading ? '...' : stats.appointmentsToday}</p>
            </div>
            <div className="summary-card">
              <h4>Citas esta semana</h4>
              <p>{loading ? '...' : stats.appointmentsWeek}</p>
            </div>
            <div className="summary-card">
              <h4>Total pacientes</h4>
              <p>{loading ? '...' : stats.patients}</p>
            </div>
            <div className="summary-card">
              <h4>Ingresos del mes</h4>
              <p>${loading ? '...' : stats.incomeMonth.toFixed(2)}</p>
            </div>
          </div>

          <div className="section-panel">
            <div className="section-card">
              <h3>Próximas citas</h3>
              <ul className="upcoming-list">
                {loading ? (
                  <li>Cargando...</li>
                ) : upcoming.length === 0 ? (
                  <li>No hay citas próximas.</li>
                ) : (
                  upcoming.map((appointment) => (
                    <li key={appointment.id}>
                      <div className="appointment-info">
                        <strong>{appointment.reason || 'Consulta médica'}</strong>
                        <span>{new Date(appointment.appointmentDate).toLocaleDateString()} · {appointment.appointmentTime || 'Hora pendiente'}</span>
                        <span className="tag">{appointment.specialty || 'General'}</span>
                      </div>
                      <div>{appointment.doctorName || 'Dr. Sin asignar'}</div>
                    </li>
                  ))
                )}
              </ul>
            </div>

            <div className="section-card stat-box">
              <div className="stat-item">
                <h4>Pacientes registrados</h4>
                <p>{loading ? '...' : stats.patients}</p>
              </div>
              <div className="stat-item">
                <h4>Ingresos mensuales</h4>
                <p>${loading ? '...' : stats.incomeMonth.toFixed(2)}</p>
              </div>
              <div className="stat-item">
                <h4>Citas activas</h4>
                <p>{loading ? '...' : stats.appointmentsWeek}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
